import os
import re
import traceback

import web

DEFAULT_LANG = 'en'


def find_i18n_namespace(path):
    """Finds i18n namespace from the path.

    >>> find_i18n_namespace('/i18n/type/type/strings.en')
    '/type/type'
    >>> find_i18n_namespace('/i18n/strings.en')
    '/'
    """
    return os.path.dirname(web.lstrips(path, '/i18n'))


